style.css:
/* AQUA ZEN — soft turquoise and rose */

:root {
  --aqua-primary: #07BEB8;
  --aqua-medium: #68D8D6;
  --aqua-light: #9CEAEF;
  --aqua-pale: #C4FFF9;
  --rose-soft: #F7D6E0;
}

/* Clean white Google background */
body {
  background-color: #FFFFFF !important;
  color: #202124 !important;
}

/* Search bar */
textarea,
input[type="text"] {
  border-radius: 24px !important;
}

/* Search and action buttons */
button {
  border-radius: 20px !important;
}

/* Soft turquoise accents */
a {
  color: #078F8B !important;
}

/* Minimal, elegant cards */
[role="button"] {
  border-radius: 14px !important;
}
